grant create on schema api,app_private,finance_private to git_tutor_commands;
create table app_private.tutor_reassignments(id uuid primary key default gen_random_uuid(),occurrence_id uuid not null references app_private.occurrences(id),original_assignment_id uuid not null references app_private.tutor_assignments(id),old_tutor_id uuid not null references app_private.tutors(id),new_tutor_id uuid not null references app_private.tutors(id),old_profile_id uuid not null references app_private.tutor_profile_versions(id),new_profile_id uuid not null references app_private.tutor_profile_versions(id),base_occurrence_version integer not null,start_at timestamptz not null,end_at timestamptz not null,roster_hash text not null,expires_at timestamptz not null,state text not null default 'proposed' check(state in('proposed','accepted','approved','committed','declined','expired')),version integer not null default 1,created_by uuid not null references app_private.accounts(id),reason text not null,approved_by uuid references app_private.accounts(id),approved_at timestamptz,committed_at timestamptz,created_at timestamptz not null default now(),check(old_tutor_id<>new_tutor_id));
create table app_private.tutor_reassignment_customer_terms(proposal_id uuid not null references app_private.tutor_reassignments(id),learner_id uuid not null references app_private.learners(id),terms jsonb not null,terms_hash text not null,primary key(proposal_id,learner_id));
create table finance_private.tutor_reassignment_tutor_terms(proposal_id uuid not null references app_private.tutor_reassignments(id),tutor_id uuid not null references app_private.tutors(id),participant_kind text not null check(participant_kind in('previous_tutor','replacement_tutor')),terms jsonb not null,terms_hash text not null,primary key(proposal_id,participant_kind));
create table app_private.tutor_reassignment_acceptances(id uuid primary key default gen_random_uuid(),proposal_id uuid not null references app_private.tutor_reassignments(id),participant_kind text not null check(participant_kind in('learner','previous_tutor','replacement_tutor')),participant_id uuid not null,actor_account_id uuid not null references app_private.accounts(id),terms_hash text not null,accepted_at timestamptz not null default now(),unique(proposal_id,participant_kind,participant_id));
create table finance_private.tutor_reassignment_obligations(id uuid primary key default gen_random_uuid(),proposal_id uuid not null unique references app_private.tutor_reassignments(id),occurrence_id uuid not null references app_private.occurrences(id),original_assignment_id uuid not null unique references app_private.tutor_assignments(id),tutor_id uuid not null references app_private.tutors(id),base_fee_agreement_id uuid references finance_private.tutor_fee_agreements(id),amount_minor bigint not null check(amount_minor between 0 and 9007199254740991),currency text not null default 'EGP' check(currency='EGP'),state text not null default 'approved_pending_T08_posting' check(state='approved_pending_T08_posting'),command_id uuid not null unique,created_at timestamptz not null default now());
create table app_private.tutor_reassignment_outcomes(proposal_id uuid primary key references app_private.tutor_reassignments(id),assignment_id uuid not null unique references app_private.tutor_assignments(id),fee_agreement_id uuid not null unique references finance_private.tutor_fee_agreements(id),obligation_id uuid not null unique references finance_private.tutor_reassignment_obligations(id),command_id uuid not null,created_at timestamptz not null default now());
do $$declare n text;s text;begin foreach n in array array['tutor_reassignments','tutor_reassignment_customer_terms','tutor_reassignment_tutor_terms','tutor_reassignment_acceptances','tutor_reassignment_obligations','tutor_reassignment_outcomes'] loop s:=case when n in('tutor_reassignment_tutor_terms','tutor_reassignment_obligations') then 'finance_private' else 'app_private' end;execute format('alter table %I.%I enable row level security',s,n);execute format('grant select,insert on %I.%I to git_tutor_commands',s,n);execute format('revoke all on %I.%I from public,anon,authenticated,service_role,git_tutor_worker',s,n);execute format('create policy teaching_commands on %I.%I to git_tutor_commands using(true) with check(true)',s,n);if n<>'tutor_reassignments' then execute format('create trigger immutable_reassignment_history before update or delete on %I.%I for each row execute function app_private.reject_immutable_change()',s,n);end if;end loop;end $$;
grant update on app_private.tutor_reassignments to git_tutor_commands;
create function app_private.teaching_reassignment_participants(p_id uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('kind',x.kind,'participant_id',x.participant_id,'accepted_at',a.accepted_at,'current',a.id is not null and a.terms_hash=x.terms_hash and app_private.payment_verified_account(a.actor_account_id) and case when x.kind='learner' then app_private.booking_can_access(a.actor_account_id,x.participant_id) else exists(select 1 from app_private.tutors t where t.id=x.participant_id and t.account_id=a.actor_account_id and app_private.has_role(t.account_id,'tutor')) end) order by x.kind,x.participant_id),'[]')
 from(select 'learner'::text kind,c.learner_id participant_id,c.terms_hash from app_private.tutor_reassignment_customer_terms c where c.proposal_id=p_id union all select t.participant_kind,t.tutor_id,t.terms_hash from finance_private.tutor_reassignment_tutor_terms t where t.proposal_id=p_id)x left join app_private.tutor_reassignment_acceptances a on a.proposal_id=p_id and a.participant_kind=x.kind and a.participant_id=x.participant_id
$$;
create function app_private.teaching_reassignment_hash(p_id uuid) returns text language sql stable security definer set search_path='' as $$select app_private.catalog_hash(jsonb_build_object('proposal_id',p_id,'customers',(select coalesce(jsonb_agg(jsonb_build_object('learner_id',learner_id,'terms_hash',terms_hash) order by learner_id),'[]') from app_private.tutor_reassignment_customer_terms where proposal_id=p_id),'tutors',(select jsonb_agg(jsonb_build_object('kind',participant_kind,'terms_hash',terms_hash) order by participant_kind) from finance_private.tutor_reassignment_tutor_terms where proposal_id=p_id)))$$;
create function app_private.teaching_reassignment_blockers(p_id uuid) returns text[] language plpgsql security definer set search_path='' as $$declare p app_private.tutor_reassignments%rowtype;o app_private.occurrences%rowtype;reasons text[]:='{}';owner uuid;begin
 select * into p from app_private.tutor_reassignments where id=p_id;select * into o from app_private.occurrences where id=p.occurrence_id;if p.id is null then raise exception 'NOT_FOUND';end if;
 if p.state in('committed','declined') then return reasons;end if;
 if p.expires_at<=now() then reasons:=array_append(reasons,'EXPIRED');end if;
 if o.version<>p.base_occurrence_version or o.tutor_id<>p.old_tutor_id or o.state not in('forming','confirmed') or o.start_at<=now() or app_private.booking_roster_fingerprint(o.id)<>p.roster_hash or not exists(select 1 from app_private.tutor_assignments where id=p.original_assignment_id and active) or not exists(select 1 from app_private.tutors where id=p.new_tutor_id and approved_profile_version_id=p.new_profile_id) then reasons:=array_append(reasons,'STALE_VERSION');end if;
 if not app_private.has_role(p.created_by,'admin') or not app_private.payment_verified_account(p.created_by) or(p.approved_by is not null and(not app_private.has_role(p.approved_by,'admin') or not app_private.payment_verified_account(p.approved_by))) or exists(select 1 from app_private.tutors t where t.id in(p.old_tutor_id,p.new_tutor_id) and(not app_private.has_role(t.account_id,'tutor') or not app_private.payment_verified_account(t.account_id))) then reasons:=array_append(reasons,'ROLE_REVOKED');end if;
 select approved_by into owner from finance_private.tutor_fee_agreements where id=o.current_fee_agreement_id;if owner is not null and not app_private.has_role(owner,'admin') then reasons:=array_append(reasons,'ROLE_REVOKED');end if;
 begin perform app_private.booking_assert_schedule(p.new_tutor_id,o.start_at,o.end_at,o.id);exception when raise_exception then if sqlerrm='SCHEDULE_CONFLICT' then reasons:=array_append(reasons,'AVAILABILITY_CONFLICT');else raise;end if;end;return reasons;
end $$;
create function app_private.teaching_reassignment_dto(p_id uuid,p_actor uuid,p_view text,p_learner_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare p app_private.tutor_reassignments%rowtype;o app_private.occurrences%rowtype;terms jsonb;hash text;participant uuid;kind text;accepted timestamptz;participants jsonb;valid boolean;complete boolean;reasons text[];result jsonb;old_name text;new_name text;begin
 select * into p from app_private.tutor_reassignments where id=p_id;if p.id is null then raise exception 'NOT_FOUND';end if;select * into o from app_private.occurrences where id=p.occurrence_id;
 if p_view='admin' then perform app_private.require_role(p_actor,'admin');hash:=app_private.teaching_reassignment_hash(p.id);select jsonb_build_object('customers',coalesce((select jsonb_agg(c.terms order by c.learner_id) from app_private.tutor_reassignment_customer_terms c where c.proposal_id=p.id),'[]'),'previous_tutor',(select t.terms from finance_private.tutor_reassignment_tutor_terms t where t.proposal_id=p.id and t.participant_kind='previous_tutor'),'replacement_tutor',(select t.terms from finance_private.tutor_reassignment_tutor_terms t where t.proposal_id=p.id and t.participant_kind='replacement_tutor')) into terms;
 elsif p_view='tutor' then perform app_private.require_role(p_actor,'tutor');select t.terms,t.terms_hash,t.tutor_id,t.participant_kind into terms,hash,participant,kind from finance_private.tutor_reassignment_tutor_terms t join app_private.tutors teacher on teacher.id=t.tutor_id where t.proposal_id=p.id and teacher.account_id=p_actor;if participant is null then raise exception 'NOT_FOUND';end if;
 elsif p_view='customer' then select c.terms,c.terms_hash,c.learner_id into terms,hash,participant from app_private.tutor_reassignment_customer_terms c where c.proposal_id=p.id and(p_learner_id is null or c.learner_id=p_learner_id) and app_private.booking_can_access(p_actor,c.learner_id) order by c.learner_id limit 1;if participant is null then raise exception 'NOT_FOUND';end if;perform app_private.assert_learner_scope(p_actor,participant,'booking');kind:='learner';
 else raise exception 'VALIDATION_ERROR';end if;
 select accepted_at into accepted from app_private.tutor_reassignment_acceptances where proposal_id=p.id and participant_kind=kind and participant_id=participant;
 participants:=app_private.teaching_reassignment_participants(p.id);complete:=not exists(select 1 from jsonb_array_elements(participants) x where not(x->>'current')::boolean);reasons:=app_private.teaching_reassignment_blockers(p.id);valid:=cardinality(reasons)=0;
 if not complete then reasons:=array_append(reasons,'PENDING_ACCEPTANCES');elsif p.state='accepted' then reasons:=array_append(reasons,'ADMIN_APPROVAL_REQUIRED');end if;
 select display_name into old_name from app_private.tutor_profile_versions where id=p.old_profile_id;select display_name into new_name from app_private.tutor_profile_versions where id=p.new_profile_id;
 result:=jsonb_build_object('proposal_id',p.id,'occurrence_id',p.occurrence_id,'base_occurrence_version',p.base_occurrence_version,'version',p.version,'state',case when p.state in('proposed','accepted','approved') and p.expires_at<=now() then 'expired' else p.state end,'expires_at',p.expires_at,'start_at',p.start_at,'end_at',p.end_at,'old_tutor',jsonb_build_object('tutor_id',p.old_tutor_id,'display_name',old_name),'new_tutor',jsonb_build_object('tutor_id',p.new_tutor_id,'display_name',new_name),'terms_hash',hash,'accepted_at',accepted,'can_accept',p_view<>'admin' and p.state in('proposed','accepted') and accepted is null and valid,'can_approve',p_view='admin' and p.state='accepted' and complete and valid,'can_commit',p_view='admin' and p.state='approved' and complete and valid,'can_decline',p.state in('proposed','accepted','approved') and p.expires_at>now(),'required_actions',to_jsonb(reasons),'view',p_view,'terms',terms);
 if p_view='admin' then result:=result||jsonb_build_object('required_acceptances',participants);end if;return result;
end $$;
create function app_private.teaching_reassignment_command(p_name text,p_input jsonb,p_key text) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare actor uuid:=app_private.require_actor();ctx jsonb;p app_private.tutor_reassignments%rowtype;o app_private.occurrences%rowtype;old_tutor app_private.tutors%rowtype;new_tutor app_private.tutors%rowtype;fee finance_private.tutor_fee_agreements%rowtype;assignment app_private.tutor_assignments%rowtype;new_fee bigint;old_amount bigint;expires timestamptz;terms jsonb;context jsonb;hash text;terms_row record;seat record;participant uuid;kind text;view text;participants jsonb;blockers text[];all_accepted boolean;result jsonb;new_assignment uuid;new_agreement uuid;obligation uuid;new_availability integer;new_terms jsonb;old_terms jsonb;event_id uuid;begin
 if p_name='propose_tutor_reassignment' then perform app_private.require_role(actor,'admin');o.id:=(p_input->>'occurrence_id')::uuid;new_tutor.id:=(p_input->>'new_tutor_id')::uuid;
 else select * into p from app_private.tutor_reassignments where id=(p_input->>'proposal_id')::uuid;if p.id is null then raise exception 'NOT_FOUND';end if;o.id:=p.occurrence_id;new_tutor.id:=p.new_tutor_id;
  if p_name in('approve_tutor_reassignment','commit_tutor_reassignment') then perform app_private.require_role(actor,'admin');
  elsif p_name='decline_tutor_reassignment' and app_private.has_role(actor,'admin') then view:='admin';
  else select x.participant_id,x.kind into participant,kind from(select c.learner_id participant_id,'learner'::text kind,c.terms_hash from app_private.tutor_reassignment_customer_terms c where c.proposal_id=p.id and app_private.booking_can_access(actor,c.learner_id) union all select t.tutor_id,t.participant_kind,t.terms_hash from finance_private.tutor_reassignment_tutor_terms t join app_private.tutors teacher on teacher.id=t.tutor_id where t.proposal_id=p.id and teacher.account_id=actor and app_private.has_role(actor,'tutor'))x where(p_name='decline_tutor_reassignment' or x.terms_hash=p_input->>'terms_hash') order by x.kind,x.participant_id limit 1;if participant is null then raise exception 'FORBIDDEN';end if;end if;
 end if;
 ctx:=app_private.booking_begin(actor,p_name,p_input,p_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;perform app_private.teaching_lock_occurrences(array[o.id],array[new_tutor.id]);select * into o from app_private.occurrences where id=o.id for update;if o.id is null then raise exception 'NOT_FOUND';end if;
 if p_name='propose_tutor_reassignment' then
  if(p_input->>'expected_version')::integer is distinct from o.version then raise exception 'VERSION_CONFLICT';end if;if o.state not in('forming','confirmed') or o.start_at<=now() or o.tutor_id=new_tutor.id then raise exception 'STATE_CONFLICT';end if;
  select * into old_tutor from app_private.tutors where id=o.tutor_id;select * into new_tutor from app_private.tutors where id=new_tutor.id;select * into fee from finance_private.tutor_fee_agreements where id=o.current_fee_agreement_id;select * into assignment from app_private.tutor_assignments where occurrence_id=o.id and active;
  if new_tutor.id is null or new_tutor.approved_profile_version_id is null or old_tutor.approved_profile_version_id is null or assignment.id is null then raise exception 'STATE_CONFLICT';end if;perform app_private.require_role(old_tutor.account_id,'tutor');perform app_private.require_role(new_tutor.account_id,'tutor');if not app_private.payment_verified_account(new_tutor.account_id) or not app_private.payment_verified_account(old_tutor.account_id) then raise exception 'FORBIDDEN';end if;
  if not exists(select 1 from app_private.tutor_profile_versions profile join app_private.offers offer on offer.id=o.offer_id where profile.id=new_tutor.approved_profile_version_id and offer.subject_id=any(profile.subject_ids)) then raise exception 'STATE_CONFLICT';end if;
  new_fee:=(p_input->>'new_fee_minor')::bigint;old_amount:=(p_input->>'old_tutor_compensation_minor')::bigint;expires:=(p_input->>'expires_at')::timestamptz;
  if new_fee is null or old_amount is null or old_amount<0 or old_amount>coalesce(fee.fee_minor,0) or expires is null or not isfinite(expires) or expires<=now() or expires>o.start_at or p_input->>'reason' is null or length(btrim(p_input->>'reason')) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
  perform app_private.assert_catalog_publication(app_private.catalog_environment(),price.environment_scope,price.is_synthetic) from app_private.pricing_versions price where price.id=o.pricing_version_id;perform app_private.assert_exact_tutor_fee(o.pricing_version_id,o.target_tier,new_fee,'EGP',o.duration_minutes);perform app_private.booking_assert_schedule(new_tutor.id,o.start_at,o.end_at,o.id);if fee.id is not null then perform app_private.require_role(fee.approved_by,'admin');end if;
  insert into app_private.tutor_reassignments(occurrence_id,original_assignment_id,old_tutor_id,new_tutor_id,old_profile_id,new_profile_id,base_occurrence_version,start_at,end_at,roster_hash,expires_at,created_by,reason) values(o.id,assignment.id,old_tutor.id,new_tutor.id,old_tutor.approved_profile_version_id,new_tutor.approved_profile_version_id,o.version,o.start_at,o.end_at,app_private.booking_roster_fingerprint(o.id),expires,actor,p_input->>'reason') returning * into p;
  context:=jsonb_build_object('proposal_id',p.id,'occurrence_id',o.id,'base_occurrence_version',o.version,'old_tutor_id',old_tutor.id,'new_tutor_id',new_tutor.id,'start_at',o.start_at,'end_at',o.end_at,'expires_at',expires);
  for seat in select e.learner_id,e.id,q.id quote_id,q.policy_version_id,q.customer_price_minor from app_private.enrollments e join app_private.quotes q on q.id=e.current_quote_id where e.occurrence_id=o.id and(e.state='confirmed' or(e.state='held' and e.hold_expires_at>now())) order by e.learner_id loop
   terms:=jsonb_build_object('kind','tutor_reassignment','learner_id',seat.learner_id,'enrollment_id',seat.id,'source_quote_id',seat.quote_id,'policy_version_id',seat.policy_version_id,'customer_price_minor',seat.customer_price_minor,'currency','EGP','charges_unchanged',true);insert into app_private.tutor_reassignment_customer_terms(proposal_id,learner_id,terms,terms_hash) values(p.id,seat.learner_id,terms,app_private.catalog_hash(context||jsonb_build_object('terms',terms)));
  end loop;
  terms:=jsonb_build_object('tutor_id',old_tutor.id,'role','previous','amount_kind','release_compensation','amount_minor',old_amount,'reference_fee_minor',fee.fee_minor,'currency','EGP','duration_minutes',o.duration_minutes,'source_fee_agreement_id',fee.id,'compensation_policy_version_id',o.pricing_version_id);insert into finance_private.tutor_reassignment_tutor_terms values(p.id,old_tutor.id,'previous_tutor',terms,app_private.catalog_hash(context||jsonb_build_object('terms',terms)));
  terms:=jsonb_build_object('tutor_id',new_tutor.id,'role','replacement','amount_kind','teaching_fee','amount_minor',new_fee,'reference_fee_minor',null,'currency','EGP','duration_minutes',o.duration_minutes,'source_fee_agreement_id',null,'compensation_policy_version_id',o.pricing_version_id);insert into finance_private.tutor_reassignment_tutor_terms values(p.id,new_tutor.id,'replacement_tutor',terms,app_private.catalog_hash(context||jsonb_build_object('terms',terms)));
  result:=app_private.booking_finish(ctx,p.id,1,jsonb_build_object('proposal_id',p.id,'state','proposed'),'tutor_reassignment_proposed',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'proposal_id',p.id));perform set_config('response.status','201',true);return result;
 end if;
 select * into p from app_private.tutor_reassignments where id=p.id for update;if(p_input->>'expected_version')::integer is distinct from p.version then raise exception 'VERSION_CONFLICT';end if;if p.state not in('proposed','accepted','approved') or p.expires_at<=now() then raise exception 'STATE_CONFLICT';end if;
 if p_name='decline_tutor_reassignment' then if p_input->>'reason' is null or length(btrim(p_input->>'reason')) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;update app_private.tutor_reassignments set state='declined',version=version+1 where id=p.id;return app_private.booking_finish(ctx,p.id,p.version+1,jsonb_build_object('state','declined'),'tutor_reassignment_declined',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'proposal_id',p.id));end if;
 blockers:=app_private.teaching_reassignment_blockers(p.id);if cardinality(blockers)>0 then if 'ROLE_REVOKED'=any(blockers) then raise exception 'FORBIDDEN';elsif 'AVAILABILITY_CONFLICT'=any(blockers) then raise exception 'SCHEDULE_CONFLICT';else raise exception 'VERSION_CONFLICT';end if;end if;
 if p_name='accept_tutor_reassignment' then
  if kind='learner' then perform app_private.assert_learner_scope(actor,participant,'booking');else perform app_private.require_role(actor,'tutor');end if;
  insert into app_private.tutor_reassignment_acceptances(proposal_id,participant_kind,participant_id,actor_account_id,terms_hash) values(p.id,kind,participant,actor,p_input->>'terms_hash') on conflict(proposal_id,participant_kind,participant_id) do nothing;
  participants:=app_private.teaching_reassignment_participants(p.id);all_accepted:=not exists(select 1 from jsonb_array_elements(participants)x where not(x->>'current')::boolean);update app_private.tutor_reassignments set state=case when all_accepted then 'accepted' else 'proposed' end,version=version+1 where id=p.id;
  return app_private.booking_finish(ctx,p.id,p.version+1,jsonb_build_object('state',case when all_accepted then 'accepted' else 'proposed' end),'tutor_reassignment_accepted',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'proposal_id',p.id));
 end if;
 participants:=app_private.teaching_reassignment_participants(p.id);if exists(select 1 from jsonb_array_elements(participants)x where not(x->>'current')::boolean) then raise exception 'CONSENT_REQUIRED';end if;
 perform app_private.require_role(p.created_by,'admin');for terms_row in select * from app_private.tutor_reassignment_acceptances where proposal_id=p.id order by participant_kind,participant_id loop if terms_row.participant_kind='learner' then perform app_private.assert_learner_scope(terms_row.actor_account_id,terms_row.participant_id,'booking');else perform app_private.require_role(terms_row.actor_account_id,'tutor');end if;end loop;
 if p_name='approve_tutor_reassignment' then if p.state<>'accepted' or p_input->>'terms_hash' is distinct from app_private.teaching_reassignment_hash(p.id) then raise exception 'STATE_CONFLICT';end if;update app_private.tutor_reassignments set state='approved',approved_by=actor,approved_at=now(),version=version+1 where id=p.id;return app_private.booking_finish(ctx,p.id,p.version+1,jsonb_build_object('state','approved'),'tutor_reassignment_approved',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'proposal_id',p.id));end if;
 if p_name<>'commit_tutor_reassignment' or p.state<>'approved' then raise exception 'STATE_CONFLICT';end if;perform app_private.require_role(p.approved_by,'admin');select * into fee from finance_private.tutor_fee_agreements where id=o.current_fee_agreement_id;if fee.id is not null then perform app_private.require_role(fee.approved_by,'admin');end if;
 select terms into new_terms from finance_private.tutor_reassignment_tutor_terms where proposal_id=p.id and participant_kind='replacement_tutor';select terms into old_terms from finance_private.tutor_reassignment_tutor_terms where proposal_id=p.id and participant_kind='previous_tutor';perform app_private.assert_catalog_publication(app_private.catalog_environment(),price.environment_scope,price.is_synthetic) from app_private.pricing_versions price where price.id=o.pricing_version_id;perform app_private.assert_exact_tutor_fee(o.pricing_version_id,o.target_tier,(new_terms->>'amount_minor')::bigint,'EGP',o.duration_minutes);new_availability:=app_private.booking_assert_schedule(p.new_tutor_id,o.start_at,o.end_at,o.id);
 insert into finance_private.tutor_fee_agreements(occurrence_id,tutor_id,pricing_version_id,target_tier,purpose,fee_minor,currency,duration_minutes,base_occurrence_version,approved_by) values(o.id,p.new_tutor_id,o.pricing_version_id,o.target_tier,'amendment',(new_terms->>'amount_minor')::bigint,'EGP',o.duration_minutes,o.version,p.approved_by) returning id into new_agreement;
 update app_private.tutor_assignments set active=false where id=p.original_assignment_id;insert into app_private.tutor_assignments(occurrence_id,tutor_id,version) values(o.id,p.new_tutor_id,(select max(version)+1 from app_private.tutor_assignments where occurrence_id=o.id)) returning id into new_assignment;
 update app_private.tutor_reservations set tutor_id=p.new_tutor_id where occurrence_id=o.id;update app_private.occurrences set tutor_id=p.new_tutor_id,current_fee_agreement_id=new_agreement,availability_version=new_availability,version=version+1,meeting_status='pending',updated_at=now() where id=o.id returning * into o;
 insert into finance_private.tutor_reassignment_obligations(proposal_id,occurrence_id,original_assignment_id,tutor_id,base_fee_agreement_id,amount_minor,command_id) values(p.id,o.id,p.original_assignment_id,p.old_tutor_id,(old_terms->>'source_fee_agreement_id')::uuid,(old_terms->>'amount_minor')::bigint,(ctx->>'command_id')::uuid) returning id into obligation;
 insert into app_private.tutor_reassignment_outcomes(proposal_id,assignment_id,fee_agreement_id,obligation_id,command_id) values(p.id,new_assignment,new_agreement,obligation,(ctx->>'command_id')::uuid);update app_private.tutor_reassignments set state='committed',committed_at=now(),version=version+1 where id=p.id;
 update app_private.calendar_events set meeting_generation=meeting_generation+1,conference_request_id=gen_random_uuid(),synced_occurrence_version=null,meeting_status='pending',join_url=null,updated_at=now() where occurrence_id=o.id;
 event_id:=gen_random_uuid();perform app_private.enqueue_event(event_id,'tutor_assignment_changed',o.id,jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'old_tutor_id',p.old_tutor_id,'new_tutor_id',p.new_tutor_id,'assignment_id',new_assignment),'calendar.sync');perform app_private.enqueue_event(event_id,'tutor_assignment_changed',o.id,jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'old_tutor_id',p.old_tutor_id,'new_tutor_id',p.new_tutor_id,'assignment_id',new_assignment),'notifications.route');
 return app_private.booking_finish(ctx,p.id,p.version+1,jsonb_build_object('state','committed','assignment_id',new_assignment,'fee_agreement_id',new_agreement),'tutor_reassignment_committed',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'proposal_id',p.id));
exception when invalid_text_representation or datetime_field_overflow then raise exception 'VALIDATION_ERROR';
end $$;
create function api.propose_tutor_reassignment(p_occurrence_id uuid,p_new_tutor_id uuid,p_new_fee_minor bigint,p_old_tutor_compensation_minor bigint,p_expires_at timestamptz,p_reason text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_reassignment_command('propose_tutor_reassignment',jsonb_build_object('occurrence_id',p_occurrence_id,'new_tutor_id',p_new_tutor_id,'new_fee_minor',p_new_fee_minor,'old_tutor_compensation_minor',p_old_tutor_compensation_minor,'expires_at',p_expires_at,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.accept_tutor_reassignment(p_proposal_id uuid,p_terms_hash text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_reassignment_command('accept_tutor_reassignment',jsonb_build_object('proposal_id',p_proposal_id,'terms_hash',p_terms_hash,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.approve_tutor_reassignment(p_proposal_id uuid,p_terms_hash text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_reassignment_command('approve_tutor_reassignment',jsonb_build_object('proposal_id',p_proposal_id,'terms_hash',p_terms_hash,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.decline_tutor_reassignment(p_proposal_id uuid,p_reason text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_reassignment_command('decline_tutor_reassignment',jsonb_build_object('proposal_id',p_proposal_id,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.commit_tutor_reassignment(p_proposal_id uuid,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_reassignment_command('commit_tutor_reassignment',jsonb_build_object('proposal_id',p_proposal_id,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.get_tutor_reassignment(p_proposal_id uuid,p_view text default 'customer',p_learner_id uuid default null) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_reassignment_dto(p_proposal_id,app_private.require_actor(),p_view,p_learner_id)$$;
create function api.list_tutor_reassignments(p_occurrence_id uuid default null,p_view text default 'customer',p_learner_id uuid default null,p_state text default null,p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();teacher uuid;after_at timestamptz;after_id uuid;rows jsonb;begin
 if p_view='admin' then perform app_private.require_role(actor,'admin');elsif p_view='tutor' then perform app_private.require_role(actor,'tutor');select id into teacher from app_private.tutors where account_id=actor;elsif p_view<>'customer' then raise exception 'VALIDATION_ERROR';end if;
 if p_limit is null or p_limit not between 1 and 100 or(p_state is not null and p_state not in('proposed','accepted','approved','committed','declined','expired')) then raise exception 'VALIDATION_ERROR';end if;if p_learner_id is not null and p_view='customer' then perform app_private.assert_learner_scope(actor,p_learner_id,'booking');end if;
 if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.teaching_reassignment_dto(x.id,actor,p_view,p_learner_id)) order by x.created_at desc,x.id desc),'[]') into rows from(select p.* from app_private.tutor_reassignments p where(p_occurrence_id is null or p.occurrence_id=p_occurrence_id) and(p_state is null or case when p.state in('proposed','accepted','approved') and p.expires_at<=now() then 'expired' else p.state end=p_state) and(p_view='admin' or(p_view='tutor' and teacher in(p.old_tutor_id,p.new_tutor_id)) or(p_view='customer' and exists(select 1 from app_private.tutor_reassignment_customer_terms c where c.proposal_id=p.id and(p_learner_id is null or c.learner_id=p_learner_id) and app_private.booking_can_access(actor,c.learner_id)))) and(p_cursor is null or(p.created_at,p.id)<(after_at,after_id)) order by p.created_at desc,p.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);
end $$;
create or replace function app_private.teaching_case_resolution(p_case uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare c app_private.unavailability_cases%rowtype;i app_private.tutor_unavailability_incidents%rowtype;o app_private.occurrences%rowtype;proposal uuid;begin
 select * into c from app_private.unavailability_cases where id=p_case;select * into i from app_private.tutor_unavailability_incidents where id=c.incident_id;select * into o from app_private.occurrences where id=c.occurrence_id;if c.state='resolved' then return jsonb_build_object('eligible',false,'proposal_id',c.resolution_proposal_id);end if;
 if o.state in('cancelled','completed') or o.tutor_id<>i.tutor_id or not(tstzrange(o.start_at,o.end_at,'[)')&&tstzrange(i.from_at,i.to_at,'[)')) then
 select id into proposal from(select id,committed_at from app_private.operation_proposals where occurrence_id=o.id and target_type='occurrence' and state='committed' and committed_at>=i.created_at union all select id,committed_at from app_private.tutor_reassignments where occurrence_id=o.id and state='committed' and new_tutor_id=o.tutor_id and committed_at>=i.created_at)x order by committed_at desc,id desc limit 1;return jsonb_build_object('eligible',o.state='cancelled' or proposal is not null,'proposal_id',proposal);end if;return jsonb_build_object('eligible',false,'proposal_id',null);
end $$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='app_private' and p.proname in('teaching_reassignment_participants','teaching_reassignment_hash','teaching_reassignment_blockers','teaching_reassignment_dto','teaching_reassignment_command'))or(n.nspname='api' and p.proname in('propose_tutor_reassignment','accept_tutor_reassignment','approve_tutor_reassignment','decline_tutor_reassignment','commit_tutor_reassignment','get_tutor_reassignment','list_tutor_reassignments')) loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end $$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
notify pgrst,'reload schema';
